import * as T from './vendor/three.module.min.js';
// Animates the real skeleton. World movement stays with Explorer; clips are in-place.
export class PartnerLocomotion{
 constructor(root,clips,forwardYaw=0,referenceSpeed=2.5){this.root=root;this.forwardYaw=forwardYaw;this.referenceSpeed=Number.isFinite(referenceSpeed)&&referenceSpeed>0?referenceSpeed:2.5;this.mixer=new T.AnimationMixer(root);this.idle=this.mixer.clipAction(clips.find(c=>c.name==='Idle'));this.walk=this.mixer.clipAction(clips.find(c=>c.name==='Walk'));this.idle.setLoop(T.LoopRepeat,Infinity).play();this.walk.setLoop(T.LoopRepeat,Infinity).play().setEffectiveWeight(0);const jumpClip=clips.find(c=>c.name==='Jump');this.jump=jumpClip?this.mixer.clipAction(jumpClip):null;if(this.jump)this.jump.setLoop(T.LoopOnce,1).setEffectiveTimeScale(0).setEffectiveWeight(0).play();this.actions=new Map();for(const clip of clips.filter(c=>['Strike','AirStrike','TurnStrike','Hit','Cast'].includes(c.name))){const a=this.mixer.clipAction(clip);a.setLoop(T.LoopOnce,1).setEffectiveTimeScale(0).setEffectiveWeight(0).play();this.actions.set(clip.name,a);}this.hitAge=Infinity;this.jumpBlend=0;this.blend=0;this.speed=0;this.heading=0;this.last=null;}
 hit(){this.hitAge=0;}
 update(dt,position,enabled=true,jumpPhase=null,{attack=null}={}){if(dt<=0)return;let speed=0,dx=0,dz=0;if(this.last){dx=position.x-this.last.x;dz=position.z-this.last.z;const d=Math.hypot(dx,dz);if(enabled&&d<Math.max(.2,dt*8))speed=d/dt;}this.last={x:position.x,z:position.z};this.speed+=(speed-this.speed)*(1-Math.exp(-dt*14));const translating=enabled&&speed>.025,moving=translating&&!Number.isFinite(jumpPhase),target=moving?1:0;this.blend+=(target-this.blend)*(1-Math.exp(-dt*(moving?14:18)));if(this.blend<.001)this.blend=0;if(translating){const desired=Math.atan2(dx,dz),difference=Math.atan2(Math.sin(desired-this.heading),Math.cos(desired-this.heading));this.heading+=difference*(1-Math.exp(-dt*12));}const jumping=Number.isFinite(jumpPhase);this.jumpBlend=jumping?1:this.jumpBlend*Math.exp(-dt*24);if(this.jumpBlend<.001)this.jumpBlend=0;if(this.jump){if(jumping)this.jump.time=T.MathUtils.clamp(jumpPhase,0,1)*this.jump.getClip().duration;this.jump.setEffectiveWeight(this.jumpBlend);}this.hitAge+=dt;const name=this.hitAge<.34?'Hit':attack?(attack.ranged?'Cast':attack.kind==='jump'?'AirStrike':attack.kind==='turn'?'TurnStrike':'Strike'):null,action=this.actions.get(name),phase=name==='Hit'?this.hitAge/.34:attack?Math.max(0,Math.min(1,attack.age/attack.duration)):0,actionWeight=enabled&&action?Math.max(0,Math.min(1,phase/.12,(1-phase)/.18)):0;for(const [id,a]of this.actions){a.setEffectiveWeight(id===name?actionWeight:0);if(id===name)a.time=phase*a.getClip().duration;}if(this.jump)this.jump.setEffectiveWeight(this.jumpBlend*(1-actionWeight));const groundedWeight=(this.jump?1-this.jumpBlend:1)*(1-actionWeight);this.walk.setEffectiveWeight(this.blend*groundedWeight);this.idle.setEffectiveWeight((1-this.blend)*groundedWeight);this.walk.setEffectiveTimeScale(moving?T.MathUtils.clamp(speed/this.referenceSpeed,0,5):0);this.mixer.update(dt);}
 dispose(){this.mixer.stopAllAction();this.mixer.uncacheRoot(this.root);}
}
